                </a>
<style>
@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&display=swap');
#wys-ultimate-header {
    --text-primary: #0f1115;
    --text-muted: #8a8f98;
    /* mesmas cores, só refinadas */
    --accent-blue: #2d6cdf;
    --accent-blue-deep: #1f4fbf;
    --accent-purple: #4a148c;
    --bg-white: #ffffff;
    --transition: 0.45s cubic-bezier(0.22, 1, 0.36, 1);
    font-family: 'Outfit', sans-serif;
    background: linear-gradient(180deg, #ffffff 0%, #fafbff 100%);
    width: 100%;
    border-bottom: 1px solid rgba(0,0,0,0.04);
}
/* container */
.header-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 3rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}
/* topbar */
.header-top {
    padding: 14px 0;
    border-bottom: 1px solid rgba(0,0,0,0.05);
}
.brand-statement {
    font-size: 10px;
    letter-spacing: 2.4px;
    color: var(--text-muted);
    font-weight: 600;
}
/* social */
.header-social {
    display: flex;
    gap: 22px;
}
.header-social a {
    text-decoration: none;
    color: var(--text-muted);
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 1.4px;
    position: relative;
    transition: var(--transition);
}
.header-social a::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 1px;
    background: var(--accent-blue);
    transition: var(--transition);
}
.header-social a:hover {
    color: var(--text-primary);
}
.header-social a:hover::after {
    width: 100%;
}
/* main */
.header-main {
    padding: 34px 0;
}
/* logo */
.main-logo img {
    width: 185px;
    transition: transform 0.5s ease, opacity 0.4s;
}
.main-logo:hover img {
    transform: scale(1.02);
}
/* nav */
.nav-list {
    list-style: none;
    display: flex;
    gap: 38px;
    margin: 0;
    padding: 0;
}
.nav-item {
    text-decoration: none !important;
    color: var(--text-primary) !important;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 1.6px;
    padding: 12px 0;
    position: relative;
    transition: var(--transition);
}
/* linha premium */
.nav-item::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 50%;
    width: 0;
    height: 1.5px;
    background: linear-gradient(90deg, var(--accent-blue), var(--accent-purple));
    transform: translateX(-50%);
    transition: width var(--transition);
}
.nav-item:hover {
    color: var(--accent-blue) !important;
}
.nav-item:hover::after {
    width: 100%;
}
/* submenu */
.has-submenu { position: relative; }
.submenu-list {
    position: absolute;
    top: 140%;
    left: 50%;
    transform: translateX(-50%) translateY(10px);
    background: rgba(255,255,255,0.85);
    backdrop-filter: blur(16px);
    box-shadow: 0 25px 60px rgba(0,0,0,0.12);
    border-radius: 12px;
    padding: 14px 0;
    min-width: 220px;
    opacity: 0;
    visibility: hidden;
    transition: var(--transition);
    z-index: 1000;
}
.has-submenu:hover .submenu-list {
    opacity: 1;
    visibility: visible;
    top: 100%;
    transform: translateX(-50%) translateY(0);
}
.submenu-list li a {
    display: block;
    padding: 13px 26px;
    text-decoration: none;
    color: var(--text-muted) !important;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 1px;
    transition: var(--transition);
}
.submenu-list li a:hover {
    background: linear-gradient(90deg, rgba(45,108,223,0.06), transparent);
    color: var(--text-primary) !important;
    padding-left: 32px;
}
/* CTA PREMIUM (mantendo azul) */
.btn-cta-premium {
    text-decoration: none !important;
    display: inline-block;
    background: linear-gradient(135deg, #005a87 0%, #30419b 100%);
    color: #ffffff !important;
    padding: 14px 34px;
    border-radius: 6px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.5px;
    box-shadow: 
        0 12px 25px rgba(48, 65, 155, 0.25),
        inset 0 1px 0 rgba(255,255,255,0.15);
    transition: var(--transition);
    position: relative;
    overflow: hidden;
}
/* brilho premium */
.btn-cta-premium::before {
    content: '';
    position: absolute;
    top: 0;
    left: -120%;
    width: 120%;
    height: 100%;
    background: linear-gradient(120deg, transparent, rgba(255,255,255,0.25), transparent);
    transition: 0.8s;
}
.btn-cta-premium:hover {
    transform: translateY(-3px);
    box-shadow: 
        0 18px 40px rgba(48, 65, 155, 0.4);
    filter: brightness(1.05);
}
.btn-cta-premium:hover::before {
    left: 120%;
}
/* responsive */
@media (max-width: 1100px) {
    .main-nav, .header-top { display: none; }
    .header-main .header-container {
        flex-direction: column;
        gap: 25px;
        padding: 20px;
    }
    .main-logo img {
        width: 150px;
    }
}</style>

