    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }

        body, html {
            height: 100%;
            width: 100%;
            background-color: #000;
            font-family: 'Plus Jakarta Sans', sans-serif;
            overflow: hidden;
            color: #ffffff;
        }

        /* Hero Background com Loop de Cor Infinito */
        .hero-bg {
            position: fixed;
            top: 0; left: 0; width: 100%; height: 100%;
            background-image: url('https://paulgomes.com.br/wp-content/uploads/2026/02/paul-gomes.png');
            background-size: cover;
            background-position: center 12%; 
            z-index: 1;
            animation: colorCycle 10s ease-in-out infinite;
        }

        @keyframes colorCycle {
            0%, 100% { filter: grayscale(100%) brightness(0.75); }
            50% { filter: grayscale(0%) brightness(0.95); }
        }

        /* Overlay de Contraste para SEO (Acessibilidade) */
        .overlay {
            position: fixed;
            top: 0; left: 0; width: 100%; height: 100%;
            background: linear-gradient(180deg, rgba(0,0,0,0.2) 0%, rgba(0,0,0,0.8) 100%);
            z-index: 2;
        }

        .main-container {
            position: relative;
            z-index: 3;
            height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: space-between;
            padding: 50px 24px 30px;
            text-align: center;
        }

        .logo-box img {
            width: 180px;
            filter: brightness(0) invert(1); /* Logo sempre branco */
            margin-bottom: 15px;
        }

        .hero-text h1 {
            font-size: 1.05rem;
            font-weight: 300;
            line-height: 1.5;
            color: #ffffff !important;
            max-width: 320px;
            margin: 0 auto 35px;
            text-shadow: 0 2px 12px rgba(0,0,0,0.9);
        }

        .nav-list {
            width: 100%;
            max-width: 400px;
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        /* Efeito LightGlass nos Botões */
        .btn-lightglass {
            background: rgba(255, 255, 255, 0.07);
            backdrop-filter: blur(18px);
            -webkit-backdrop-filter: blur(18px);
            border: 1px solid rgba(255, 255, 255, 0.15);
            padding: 18px 24px;
            border-radius: 20px;
            text-decoration: none;
            display: flex;
            align-items: center;
            transition: 0.4s cubic-bezier(0.16, 1, 0.3, 1);
            color: #ffffff !important;
        }

        .btn-lightglass:hover {
            background: rgba(255, 255, 255, 0.12);
            border-color: rgba(255, 255, 255, 0.6);
            transform: translateY(-2px);
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
        }

        /* Força todos os elementos internos do botão para branco */
        .btn-lightglass span, .btn-lightglass i {
            color: #ffffff !important;
            opacity: 1;
        }

        .btn-lightglass i {
            font-size: 1.1rem;
            margin-right: 15px;
            width: 25px;
            text-align: center;
        }

        .btn-lightglass span {
            flex: 1;
            text-align: left;
            font-weight: 600;
            font-size: 0.95rem;
            letter-spacing: 0.3px;
        }

        .arrow-icon {
            font-size: 0.75rem;
            opacity: 0.4;
            color: #ffffff !important;
        }

        footer {
            margin-top: auto;
        }

        .privacy-cta {
            font-size: 0.65rem;
            text-transform: uppercase;
            letter-spacing: 2px;
            color: #ffffff !important;
            opacity: 0.5;
            text-decoration: none;
            transition: 0.3s;
        }

        .privacy-cta:hover { opacity: 1; }
    </style>
</head>
<body>

